CLASS = 'rc_pretag_ci_repair_cases.CiRepairCompositionCases'
DIGEST = '19fcc26fea5257aa5d16a46c713e5bb65f7528f377cfd6c7618bd3c0547ff9c0'
USES = re.compile(rb'^ *(?:- )?uses: [A-Za-z0-9_.-]+/[A-Za-z0-9_./-]+@[0-9a-f]{40}(?: #[^\n]*)?$')


def ci_policy(data):
    """Read-only token and SHA-pinned actions only; never widened by this layer."""
    lines = data.splitlines()
    assert data.count(b'permissions:') == 1 and b'permissions:\n  contents: read\n' in data, 'ci_repair permissions'
    # Intentionally strict: any whole-word 'write' anywhere in ci.yml rejects, false positives on prose accepted.
    assert not re.search(rb'\b(write|write-all)\b', data), 'ci_repair write permission'
    uses = [line for line in lines if b'uses:' in line]
    assert uses and all(USES.match(line) for line in uses), 'ci_repair unpinned action'
    return True


def normalize(path, current):
    """Reverse only sealed new bytes; historical passthrough is a finite pin list."""
    from rc_pretag_reap_safe_profile import normalize as reap_safe_bytes
    current = reap_safe_bytes(path, current)
    assert type(path) is str and type(current) is bytes, 'ci_repair inverse input'
    if path not in BASE_PINS:
        return current
    identity = o.pin(current)
    baseline = BASE_PINS[path]
    if identity == baseline[1:3] or identity in PRIOR_PINS.get(path, ()):
        return current
    row = SOURCE_PINS[path]
    assert (identity, len(current), len(current.splitlines())) == (row[1:3], row[3], row[4]), path
    restored = current
    for before, after in reversed(FRAGMENTS[path]):
        assert before and restored.count(before) == 1, 'ci_repair fragment missing or duplicated'
        restored = restored.replace(before, after, 1)
    assert (o.pin(restored), len(restored), len(restored.splitlines())) == (
        baseline[1:3], baseline[3], baseline[4]), 'complete ci_repair inverse'
    return restored


def topology(ref, root, git, release):
    """Only D[M], I[M,D], J[R,I] with M exactly 35559f67; anything else delegates."""
    if release != p.R:
        raise o.TopologyError('ci_repair_release_anchor')
    parents = o._parents(ref, root, git)
    if parents == [M]:
        kind, tip, source = 'nonrelease', ref, ref
    elif len(parents) == 2 and parents[0] == M:
        kind, tip, source = 'nonrelease', ref, parents[1]
    elif len(parents) == 2 and parents[0] == p.R:
        kind, tip = 'release', parents[1]
        feature_parents = o._parents(tip, root, git)
        if len(feature_parents) != 2 or feature_parents[0] != M:
            raise o.TopologyError('ci_repair_feature_parents')
        source = feature_parents[1]
    else:
        raise o.TopologyError('ci_repair_candidate_parents')
    if o._parents(source, root, git) != [M]:
        raise o.TopologyError('ci_repair_candidate_parent')
    return kind, tip, source


def anchor(root, git, entries, historical, release, release_tree, documents):
    """Exact M bytes; BASE freshly validated by the existing chain; M differs from BASE only by pinned ci.yml."""
    assert tuple(o._parents(M, root, git)) == M_PARENTS, 'ci_repair M parents'
    assert git('rev-parse', M + '^{tree}', root=root).decode().strip() == M_TREE, 'ci_repair M tree'
    raw = git('cat-file', 'commit', M, root=root)
    assert (len(raw), hashlib.sha256(raw).hexdigest()) == M_RAW, 'ci_repair M raw'
    baseline = p.selected_profile(BASE, root, git, entries, historical, release, release_tree, documents)
    assert baseline == entries(BASE, root)
    anchored = entries(M, root)
    assert anchored.keys() == baseline.keys() and {k for k in anchored if anchored[k] != baseline[k]} == {CI}
    assert anchored[CI] == (CI_PIN[0], 'blob', CI_PIN[1]), 'ci_repair ci.yml blob'
    data = git('cat-file', 'blob', anchored[CI][2], root=root)
    assert o.pin(data) == CI_PIN[1:3] and (len(data), len(data.splitlines())) == CI_PIN[3:5], 'ci_repair ci.yml bytes'
    ci_policy(data)
    return baseline, anchored


def content(ref, root, git, entries, historical, release, release_tree, documents):
    """Exact M anchor, exact candidate pins and complete reviewed delta against BASE."""
    assert (release, release_tree, documents) == (p.R, p.R_TREE, p.R_DOCUMENTS)
    baseline, anchored = anchor(root, git, entries, historical, release, release_tree, documents)
    actual, paths = entries(ref, root), CAPS.keys()
    assert SOURCE_PINS.keys() == paths - {PROFILE} and FRAGMENTS.keys() == BASE_PINS.keys() and PRIOR_PINS.keys() <= BASE_PINS.keys()
    assert baseline.keys() & paths == BASE_PINS.keys() and actual.keys() == baseline.keys() | paths
    assert {path for path in actual if actual[path] != baseline.get(path)} == paths
    assert all(actual[path] == value for path, value in anchored.items() if path not in paths - {CI})
    assert all(actual[path] == (row[0], 'blob', row[1]) for path, row in SOURCE_PINS.items())
    data = {path: git('cat-file', 'blob', actual[path][2], root=root) for path in paths}
    for path, (mode, blob, digest, size, count) in SOURCE_PINS.items():
        assert mode == '100644' and o.pin(data[path]) == (blob, digest), path
        assert (len(data[path]), len(data[path].splitlines())) == (size, count), path
    for path, row in BASE_PINS.items():
        assert baseline[path] == (row[0], 'blob', row[1]), path
        assert normalize(path, data[path]) == git('cat-file', 'blob', baseline[path][2], root=root), path
    ci_policy(data[CI])
    p.authenticated._budgets(ref, BASE, root, git, data, CAPS, DELTA_LIMIT, 'ci_repair_delta_budget')
    return actual


def select(ref, root, git, entries, historical, release, release_tree, documents):
    """Only topology mismatch delegates; selected and historical content errors escape."""
    ref = o._commit(ref, root, git)
    import rc_pretag_reap_safe_profile as reap_safe
    selected = reap_safe.select(ref, root, git, entries, historical, release, release_tree, documents)
    if selected is not None:
        return selected
    try:
        kind, tip, source = topology(ref, root, git, release)
    except o.TopologyError:
        return None
    expected = content(source, root, git, entries, historical, release, release_tree, documents)
    assert entries(tip, root) == expected
    if kind == 'release':
        return o.release_content(ref, expected, root, git, entries, release, release_tree, documents)
    return expected
